<script setup>
import {Button,Uploader} from 'vant';import 'vant/es/button/style';import 'vant/es/uploader/style';
const props=defineProps({controller:{type:Object,required:true},model:{type:Object,required:true}}),a=props.controller.actions;
const photo=files=>a.photo((Array.isArray(files)?files:[files]).map(item=>item.file));
function original(canvas,page){if(canvas)window.GrowingHandwriting?.draw(canvas,page);}
</script>
<template><section class="student-correction-pad"><div class="correction-actions"><Uploader accept="image/jpeg,image/png,image/webp" capture="environment" :show-upload-list="false" :after-read="photo" :disabled="model.locked"><Button :disabled="model.locked" :loading="model.importing">拍照答案</Button></Uploader><Uploader accept="image/jpeg,image/png,image/webp" multiple :show-upload-list="false" :after-read="photo" :disabled="model.locked"><Button :disabled="model.locked">从相册选择</Button></Uploader></div><ol class="correction-photos"><li v-for="(image,i) in model.draft.handwriting.photos||[]" :key="i"><img :src="image" :alt="'本次答案第 '+(i+1)+' 页'"/><Button icon="cross" :aria-label="'移除第 '+(i+1)+' 页答案照片'" :disabled="model.locked" @click="a.removePhoto(i)"/></li></ol><details v-if="model.draft.handwriting.pages?.some(page=>page.length)"><summary>查看以前保存的笔迹（只读）</summary><canvas v-for="(page,i) in model.draft.handwriting.pages" :key="i" :ref="el=>original(el,page)" width="800" height="1100" :aria-label="'历史笔迹第 '+(i+1)+' 页，只读'"/></details></section></template>
<style scoped>.student-correction-pad{min-width:0}.correction-actions{display:flex;align-items:center;gap:10px;flex-wrap:wrap;margin:14px 0}.student-correction-pad.student-correction-pad :deep(.van-button){min-height:44px;font:inherit}.student-correction-pad canvas{display:block;width:100%;height:auto;max-width:800px;border:1px solid #d9e2d9;background:repeating-linear-gradient(#fff 0px,#fff 39px,#edf0ec 40px);touch-action:auto}.correction-photos{list-style:none;padding:0;display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:12px}.correction-photos li{position:relative;min-width:0}.correction-photos img{display:block;max-width:100%;height:auto}.correction-photos :deep(.van-button){position:absolute;top:5px;right:5px;width:44px;padding:0;background:#fff}.student-correction-pad.student-correction-pad :deep(.van-dialog .correction-actions){justify-content:center;padding:0 14px}</style>

